<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Document\Theme\Domain\ThemeRef;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\ThemeAssetThemeVO;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\ThemeAssetCodeVO;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\ThemeAssetTypeVO;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\ThemeAssetContentVO;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\ThemeAssetEnabledVO;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\ThemeAssetVersionVO;
use Civi\Lughauth\Features\Document\ThemeAsset\Application\Usecase\Create\ThemeAssetCreateResult;
use PHPUnit\Framework\TestCase;

final class ThemeAssetCreateResultUnitTest extends TestCase
{
    public function test(): void
    {
        $value = new ThemeAssetCreateResult();
        $themeOneValue = new ThemeRef('one');
        $themeOtherValue = new ThemeRef('other');
        $copy = $value->theme($themeOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new ThemeRef('one'), $value->getTheme());
        $this->assertNotEquals(new ThemeRef('other'), $value->getTheme());
        $this->assertEquals(new ThemeRef('one'), $value->getThemeOrCurrent(ThemeAssetThemeVO::from($themeOtherValue))->value());
        $this->assertNotEquals(new ThemeRef('other'), $value->getThemeOrCurrent(ThemeAssetThemeVO::from($themeOtherValue))->value());
        $value->unsetTheme();
        $this->assertEquals(new ThemeRef('other'), $value->getThemeOrCurrent(ThemeAssetThemeVO::from($themeOtherValue))->value());
        $this->assertNotEquals(new ThemeRef('one'), $value->getThemeOrCurrent(ThemeAssetThemeVO::from($themeOtherValue))->value());
        $codeOneValue = 'one';
        $codeOtherValue = 'other';
        $copy = $value->code($codeOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getCode());
        $this->assertNotEquals('other', $value->getCode());
        $this->assertEquals('one', $value->getCodeOrCurrent(ThemeAssetCodeVO::from($codeOtherValue))->value());
        $this->assertNotEquals('other', $value->getCodeOrCurrent(ThemeAssetCodeVO::from($codeOtherValue))->value());
        $value->unsetCode();
        $this->assertEquals('other', $value->getCodeOrCurrent(ThemeAssetCodeVO::from($codeOtherValue))->value());
        $this->assertNotEquals('one', $value->getCodeOrCurrent(ThemeAssetCodeVO::from($codeOtherValue))->value());
        $typeOneValue = 'one';
        $typeOtherValue = 'other';
        $copy = $value->type($typeOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getType());
        $this->assertNotEquals('other', $value->getType());
        $this->assertEquals('one', $value->getTypeOrCurrent(ThemeAssetTypeVO::from($typeOtherValue))->value());
        $this->assertNotEquals('other', $value->getTypeOrCurrent(ThemeAssetTypeVO::from($typeOtherValue))->value());
        $value->unsetType();
        $this->assertEquals('other', $value->getTypeOrCurrent(ThemeAssetTypeVO::from($typeOtherValue))->value());
        $this->assertNotEquals('one', $value->getTypeOrCurrent(ThemeAssetTypeVO::from($typeOtherValue))->value());
        $contentOneValue = 'store://bin';
        $contentOtherValue = 'store://obin';
        $copy = $value->content($contentOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('store://bin', $value->getContent());
        $this->assertNotEquals('store://obin', $value->getContent());
        $this->assertEquals('bin', $value->getContentOrCurrent(ThemeAssetContentVO::from($contentOtherValue))->value());
        $this->assertNotEquals('obin', $value->getContentOrCurrent(ThemeAssetContentVO::from($contentOtherValue))->value());
        $value->unsetContent();
        $this->assertEquals('obin', $value->getContentOrCurrent(ThemeAssetContentVO::from($contentOtherValue))->value());
        $this->assertNotEquals('bin', $value->getContentOrCurrent(ThemeAssetContentVO::from($contentOtherValue))->value());
        $enabledOneValue = true;
        $enabledOtherValue = false;
        $copy = $value->enabled($enabledOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(true, $value->isEnabled());
        $this->assertNotEquals(false, $value->isEnabled());
        $this->assertEquals(true, $value->getEnabledOrCurrent(ThemeAssetEnabledVO::from($enabledOtherValue))->value());
        $this->assertNotEquals(false, $value->getEnabledOrCurrent(ThemeAssetEnabledVO::from($enabledOtherValue))->value());
        $value->unsetEnabled();
        $this->assertEquals(false, $value->getEnabledOrCurrent(ThemeAssetEnabledVO::from($enabledOtherValue))->value());
        $this->assertNotEquals(true, $value->getEnabledOrCurrent(ThemeAssetEnabledVO::from($enabledOtherValue))->value());
        $versionOneValue = 1;
        $versionOtherValue = 2;
        $copy = $value->version($versionOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(1, $value->getVersion());
        $this->assertNotEquals(2, $value->getVersion());
        $this->assertEquals(1, $value->getVersionOrCurrent(ThemeAssetVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(2, $value->getVersionOrCurrent(ThemeAssetVersionVO::from($versionOtherValue))->value());
        $value->unsetVersion();
        $this->assertEquals(2, $value->getVersionOrCurrent(ThemeAssetVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(1, $value->getVersionOrCurrent(ThemeAssetVersionVO::from($versionOtherValue))->value());
        $this->assertSame($value, $copy);
    }
}
